function hash(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}export function canaryAssignment(subjectId,{percent=0,flagEnabled=true}={}){if(!flagEnabled)return false;const p=Math.max(0,Math.min(100,Number(percent)));return (hash(subjectId)%10000)<p*100}export function featureDecision(flag,{subjectId,entitled=true,safety=false}={}){if(safety)return {enabled:true,reason:'SAFETY_ALWAYS_ON'};if(!entitled)return {enabled:false,reason:'NOT_ENTITLED'};if(flag.mode==='OFF')return {enabled:false,reason:'FLAG_OFF'};if(flag.mode==='ON')return {enabled:true,reason:'FLAG_ON'};return {enabled:canaryAssignment(subjectId,{percent:flag.percent,flagEnabled:true}),reason:'CANARY'}}
